1	'use strict';
2	const fs = require('fs');
3	const path = require('path');
4	const { execSync } = require('child_process');
5	
6	const LEARNING_DIR = path.join(process.env.HOME || process.cwd(), '.claude', 'nisaba', 'learning');
7	const PROJECT_LEARNING_DIR = path.join(process.cwd(), '.claude', 'nisaba', 'learning');
8	const SESSIONS_DIR = path.join(PROJECT_LEARNING_DIR, 'sessions');
9	
10	function buildDreamPrompt() {
11	  const sessions = loadRecentSessions(20);
12	  const lastDreamTime = getLastDreamTime();
13	
14	  const sessionBlocks = sessions.map((s, i) => {
15	    const isNew = new Date(s.ts).getTime() > lastDreamTime;
16	    const marker = isNew ? '★ NEW' : '  OLD';
17	    const corrections = s.corrections?.length > 0
18	      ? `\nCORRECTIONS DETECTED:\n${s.corrections.map(c => `  - "${c}"`).join('\n')}`
19	      : '';
20	    return `${marker} | ${s.ts} | agents:[${s.agents_run.map(a => a.type).join(', ')}] | skills:[${s.skills_read.join(', ')}]
21	Human messages:
22	${s.human_messages.map((m, idx) => `  ${idx + 1}. "${m}"`).join('\n')}${corrections}
23	${s.agents_run.map(a => `${a.type} output: "${a.output_preview}"`).join('\n')}`;
24	  }).join('\n\n---\n\n');
25	
26	  return `You analyze recent Claude Code sessions and write one-line rules to prevent repeated mistakes.
27	
28	★ = new since last dream. These are fresh signal. OLD sessions provide pattern confirmation.
29	
30	## Sessions
31	${sessionBlocks}
32	
33	## Where to write rules
34	- ${path.join(LEARNING_DIR, 'global.md')} — lessons that apply to EVERY agent in EVERY project
35	- ${path.join(LEARNING_DIR, 'agents/{type}.md')} — lessons for one specific agent type, all projects
36	- ${path.join(PROJECT_LEARNING_DIR, 'global.md')} — lessons for every agent in THIS project only
37	- ${path.join(PROJECT_LEARNING_DIR, 'agents/{type}.md')} — lessons for one agent in THIS project only
38	
39	Write the rules now. Read target files first. Write only what is new. Stop after 5 rules.`;
40	}
41	
42	function loadRecentSessions(max) {
43	  const sessions = [];
44	  if (!fs.existsSync(SESSIONS_DIR)) return sessions;
45	  const files = fs.readdirSync(SESSIONS_DIR).filter(f => f.endsWith('.jsonl')).sort().reverse();
46	  for (const file of files) {
47	    const lines = fs.readFileSync(path.join(SESSIONS_DIR, file), 'utf8').split('\n').filter(Boolean);
48	    for (const line of lines) {
49	      try {
50	        sessions.push(JSON.parse(line));
51	        if (sessions.length >= max) return sessions;
52	      } catch {}
53	    }
54	  }
55	  return sessions;
56	}
57	
58	function getLastDreamTime() {
59	  const lockFile = path.join(PROJECT_LEARNING_DIR, '.dream-lock');
60	  if (!fs.existsSync(lockFile)) return 0;
61	  try { return parseInt(fs.readFileSync(lockFile, 'utf8')); }
62	  catch { return 0; }
63	}
64	
65	const prompt = buildDreamPrompt();
66	const promptFile = path.join(PROJECT_LEARNING_DIR, '.dream-prompt.txt');
67	fs.mkdirSync(path.dirname(promptFile), { recursive: true });
68	fs.writeFileSync(promptFile, prompt);
69	
70	try {
71	  execSync(
72	    `claude -p --model claude-haiku-4-5 "$(cat ${promptFile})" --allowedTools Write,Edit,Read`,
73	    { cwd: process.cwd(), timeout: 120_000, stdio: 'ignore' }
74	  );
75	} catch (e) {
76	  fs.appendFileSync(
77	    path.join(PROJECT_LEARNING_DIR, 'dream-errors.log'),
78	    `${new Date().toISOString()}: ${e.message}\n`
79	  );
80	}
