1	'use strict';
2	const fs = require('fs');
3	const path = require('path');
4	const crypto = require('crypto');
5	const { spawn } = require('child_process');
6	
7	const PROJECT_LEARNING_DIR = path.join(process.cwd(), '.claude', 'nisaba', 'learning');
8	const SESSIONS_DIR = path.join(PROJECT_LEARNING_DIR, 'sessions');
9	
10	const COOLDOWN_MS = 4 * 3_600_000;
11	const MIN_SESSIONS = 3;
12	
13	let raw = '';
14	process.stdin.setEncoding('utf8');
15	process.stdin.on('data', c => raw += c);
16	process.stdin.on('end', () => {
17	  try {
18	    const event = JSON.parse(raw);
19	    const { session_id, transcript_path } = event;
20	
21	    if (!transcript_path || !fs.existsSync(transcript_path)) {
22	      process.exit(0); return;
23	    }
24	
25	    const obs = parseSession(session_id || 'unknown', transcript_path);
26	    writeObservation(obs);
27	
28	    // Session lifecycle: extract learnings + write journal
29	    try {
30	      const reflect = require('./session-reflect.js');
31	      reflect.run();
32	    } catch (_) {}
33	
34	    if (shouldDream()) spawnDream();
35	  } catch (e) {}
36	  process.exit(0);
37	});
38	
39	function parseSession(sessionId, transcriptPath) {
40	  const lines = fs.readFileSync(transcriptPath, 'utf8').split('\n').filter(Boolean);
41	  const humanMessages = [];
42	  const agentsRun = [];
43	  const skillsRead = new Set();
44	  const corrections = [];
45	  let pendingAgent = null;
46	
47	  for (const line of lines) {
48	    let e;
49	    try { e = JSON.parse(line); } catch { continue; }
50	
51	    const role = e.message?.role;
52	    const content = e.message?.content;
53	    if (!Array.isArray(content)) continue;
54	
55	    for (const block of content) {
56	      if (role === 'user' && block.type === 'text') {
57	        const text = (block.text || '').trim();
58	        if (text.length > 2) {
59	          humanMessages.push(text.slice(0, 300));
60	          const correctionPatterns = [
61	            /\bno[,.]?\s+(don'?t|remove|stop|never|avoid)/i,
62	            /\bwrong\b/i,
63	            /\bnot like that\b/i,
64	            /\bstill\b.*\bsame\b/i,
65	            /\bagain\b/i,
66	            /\bwtf\b/i,
67	            /\bplease don'?t\b/i
68	          ];
69	          const isCorrection = correctionPatterns.some(p => p.test(text));
70	          if (isCorrection) corrections.push(text.slice(0, 200));
71	        }
72	      }
73	
74	      if (role === 'user' && block.type === 'tool_result' && pendingAgent) {
75	        const parts = Array.isArray(block.content) ? block.content : [{ type: 'text', text: String(block.content || '') }];
76	        const meta = parts.find(p => p.type === 'text' && p.text?.includes('agentId:'));
77	        if (meta) {
78	          const output = parts.filter(p => p !== meta && p.type === 'text' && p.text).map(p => p.text).join('\n').trim();
79	          agentsRun.push({
80	            type: pendingAgent.type,
81	            prompt_preview: pendingAgent.prompt,
82	            output_preview: output.slice(0, 400).replace(/\s+/g, ' '),
83	          });
84	          pendingAgent = null;
85	        }
86	      }
87	
88	      if (role === 'assistant' && block.type === 'tool_use') {
89	        if (block.name === 'Agent') {
90	          const t = (block.input?.subagent_type || 'unknown').replace(/^[^:]+:/, '').toLowerCase();
91	          pendingAgent = { type: t, prompt: (block.input?.prompt || '').slice(0, 150) };
92	        }
93	        if (block.name === 'Read') {
94	          const m = (block.input?.file_path || '').match(/skills\/([^/]+)\/SKILL\.md$/i);
95	          if (m) skillsRead.add(m[1]);
96	        }
97	      }
98	    }
99	  }
100	
101	  return {
102	    id: `sess-${Date.now()}-${crypto.randomBytes(2).toString('hex')}`,
103	    ts: new Date().toISOString(),
104	    session_id: sessionId,
105	    project: path.basename(process.cwd()),
106	    human_messages: humanMessages,
107	    corrections: corrections,
108	    agents_run: agentsRun,
109	    skills_read: [...skillsRead],
110	  };
111	}
112	
113	function writeObservation(obs) {
114	  fs.mkdirSync(SESSIONS_DIR, { recursive: true });
115	  const date = new Date().toISOString().split('T')[0];
116	  const file = path.join(SESSIONS_DIR, `${date}.jsonl`);
117	  fs.appendFileSync(file, JSON.stringify(obs) + '\n');
118	}
119	
120	function shouldDream() {
121	  const lockFile = path.join(PROJECT_LEARNING_DIR, '.dream-lock');
122	  if (fs.existsSync(lockFile)) {
123	    const lastRun = parseInt(fs.readFileSync(lockFile, 'utf8'));
124	    if (Date.now() - lastRun < COOLDOWN_MS) return false;
125	  }
126	  const date = new Date().toISOString().split('T')[0];
127	  const file = path.join(SESSIONS_DIR, `${date}.jsonl`);
128	  if (!fs.existsSync(file)) return false;
129	  const count = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).length;
130	  return count >= MIN_SESSIONS;
131	}
132	
133	function spawnDream() {
134	  const lockFile = path.join(PROJECT_LEARNING_DIR, '.dream-lock');
135	  fs.mkdirSync(path.dirname(lockFile), { recursive: true });
136	  fs.writeFileSync(lockFile, String(Date.now()));
137	
138	  const dreamScript = path.join(__dirname, 'nisaba-dream.js');
139	  const child = spawn('node', [dreamScript], {
140	    detached: true,
141	    stdio: 'ignore',
142	    cwd: process.cwd()
143	  });
144	  child.unref();
145	}
