1	#!/usr/bin/env node
2	// PreToolUse — 4-tier compaction + cross-terminal memory awareness
3	'use strict';
4	const fs = require('fs');
5	const path = require('path');
6	const os = require('os');
7	const bus = require('./memory-bus.js');
8	const ss = require('./session-state.js');
9	
10	const STATE_FILE = '/Users/marcelspatz/NUDIMMUD/.claude/state/session-state.json';
11	const MEMORY_INDEX = path.join(os.homedir(), '.claude', 'projects', '-Users-marcelspatz-NUDIMMUD', 'memory', 'MEMORY.md');
12	
13	const HEAVY_TOOLS = new Set(['Agent', 'WebSearch', 'WebFetch', 'TaskCreate']);
14	
15	function getTier(pct) {
16	  if (pct < 55) return 0;
17	  if (pct < 65) return 1;
18	  if (pct < 78) return 2;
19	  if (pct < 88) return 3;
20	  return 4;
21	}
22	
23	function buildHint(state) {
24	  const parts = [];
25	  if (state.git?.branch) parts.push(`branch=${state.git.branch}`);
26	  const files = (state.files_written || []).slice(-3);
27	  if (files.length) parts.push(`files=${files.map(f => path.basename(f)).join(',')}`);
28	  if (state.aversions?.length) parts.push(`aversion="${state.aversions.slice(-1)[0]}"`);
29	  return `/compact Preserve: ${parts.join(' | ')}`;
30	}
31	
32	function emitContext(msg) {
33	  process.stderr.write(JSON.stringify({
34	    hookSpecificOutput: { hookEventName: 'PreToolUse', additionalContext: msg }
35	  }) + '\n');
36	}
37	
38	try {
39	    const input = fs.readFileSync(0, 'utf-8').trim();
40	    if (!input) process.exit(0);
41	    const event = JSON.parse(input);
42	
43	    const toolName = event?.tool_name || event?.tool || '';
44	    const toolInput = JSON.stringify(event?.tool_input || {});
45	
46	    // ── Cross-terminal memory check ──────────────────────────────────────────
47	    const sessionId = bus.getSessionId();
48	    const currentBus = bus.readBus();
49	    const session = bus.readSession(sessionId);
50	
51	    if (
52	        currentBus.sequence > session.lastSeenSequence &&
53	        currentBus.writerSession &&
54	        currentBus.writerSession !== sessionId
55	    ) {
56	        let memoryContent = '';
57	        try { memoryContent = fs.readFileSync(MEMORY_INDEX, 'utf8').trim(); } catch (_) {}
58	
59	        const changedFiles = (currentBus.files || []).join(', ') || 'memory files';
60	        emitContext([
61	            `[CROSS-TERMINAL MEMORY UPDATE] Another Claude session wrote: ${changedFiles}`,
62	            `Written at: ${currentBus.lastWrite}`,
63	            '',
64	            'Current memory index:',
65	            memoryContent || '(could not read MEMORY.md)',
66	        ].join('\n'));
67	
68	        session.lastSeenSequence = currentBus.sequence;
69	        bus.writeSession(sessionId, session);
70	        bus.cleanOldSessions();
71	    }
72	
73	    // ── Tier-based compaction dispatch ──────────────────────────────────────
74	    const state = ss.read();
75	    const contextPct = state?.context?.pct || 0;
76	    const tier = getTier(contextPct);
77	
78	    if (tier >= 1 && state) {
79	        const lastFiredPct = state.context?.last_fired_pct || 0;
80	        const shouldFire = tier === 1 || Math.abs(contextPct - lastFiredPct) >= 3;
81	
82	        if (shouldFire) {
83	            const hint = buildHint(state);
84	            const historyEntry = { tier, pct: contextPct, ts: new Date().toISOString() };
85	
86	            if (tier === 1) {
87	                // Log only, no output
88	                ss.update(s => {
89	                    s.compact_history.push({ ...historyEntry, action: 'logged' });
90	                    s.context.tier = tier;
91	                });
92	            } else if (tier === 2) {
93	                ss.update(s => {
94	                    s.compact_history.push({ ...historyEntry, hint, action: 'soft_prompt' });
95	                    s.context.tier = tier;
96	                    s.context.last_fired_pct = contextPct;
97	                });
98	                emitContext(
99	                    `CONTEXT AT ${contextPct.toFixed(0)}%: Consider running /compact now.\n` +
100	                    `Pre-built hint: ${hint}`
101	                );
102	            } else if (tier === 3) {
103	                ss.update(s => {
104	                    s.compact_history.push({ ...historyEntry, hint, action: 'hard_prompt' });
105	                    s.context.tier = tier;
106	                    s.context.last_fired_pct = contextPct;
107	                });
108	                emitContext(
109	                    `CONTEXT CRITICAL AT ${contextPct.toFixed(0)}%: /compact STRONGLY RECOMMENDED.\n` +
110	                    `Run NOW: ${hint}\n` +
111	                    (state.aversions?.length ? `Aversion: ${state.aversions.slice(-1)[0]}` : '')
112	                );
113	            } else if (tier === 4) {
114	                ss.update(s => {
115	                    s.compact_history.push({ ...historyEntry, hint, action: 'critical' });
116	                    s.context.tier = tier;
117	                    s.context.last_fired_pct = contextPct;
118	                });
119	                // Trigger early learning extraction async
120	                const { spawn } = require('child_process');
121	                spawn('node', [path.join(__dirname, 'session-reflect.js'), '--mid-session'], {
122	                    detached: true, stdio: 'ignore', cwd: process.cwd()
123	                }).unref();
124	                emitContext(
125	                    `CONTEXT AT ${contextPct.toFixed(0)}%: Session approaching limit. Auto-extracted learnings written.\n` +
126	                    `You MUST /compact immediately: ${hint}`
127	                );
128	            }
129	        }
130	    }
131	
132	    // ── Legacy token economy check (score-based) ─────────────────────────────
133	    const isHeavy = HEAVY_TOOLS.has(toolName);
134	    const score = (isHeavy ? 600 : 100) + Math.floor(toolInput.length / 10);
135	
136	    if (contextPct > 75 && isHeavy) {
137	        emitContext(`TOKEN_ECONOMY: Context at ${contextPct.toFixed(0)}% — "${toolName}" is expensive. Consider offloading to @deepseek or @qwen.`);
138	    } else if (score > 2000 && contextPct > 60) {
139	        emitContext(`TOKEN_ECONOMY: High-cost op "${toolName}" (score: ${score}). Recommend: offload via @swarm or @kimi.`);
140	    }
141	
142	    process.exit(0);
143	} catch (_) {
144	    process.exit(0);
145	}
