32	
33	        if (isError && errorSnippet) {
34	            state.errors.push({ ts: new Date().toISOString(), tool: toolName, snippet: errorSnippet });
35	        }
36	
37	        // Track file writes
38	        if (['Edit', 'Write'].includes(toolName) && filePath) {
39	            const rel = filePath.replace('/Users/marcelspatz/NUDIMMUD/', '');
40	            if (!state.files_written.includes(rel)) state.files_written.push(rel);
41	        }
42	
43	        // Track skill reads (Read tool on a SKILL.md)
44	        if (toolName === 'Read' && filePath) {
45	            const m = filePath.match(/skills\/([^/]+)\/SKILL\.md$/i);
