49	        // Track skill writes
50	        if (['Edit', 'Write'].includes(toolName) && filePath) {
51	            const m = filePath.match(/skills\/([^/]+)\/SKILL\.md$/i);
52	            if (m && !state.skills_written.includes(m[1])) state.skills_written.push(m[1]);
53	        }
54	    });
