56	    // ── Cross-terminal memory bus: sync memory file writes ───────────────────
57	    if (['Edit', 'Write'].includes(toolName) && filePath && bus.isMemoryFile(filePath)) {
58	        const sessionId = bus.getSessionId();
59	        bus.writeBus(sessionId, [path.basename(filePath)]);
60	    }
61	
62	    // ── Design memory capture (Edit/Write on design files only) ──────────────
63	    if (['Edit', 'Write'].includes(toolName) && filePath && DESIGN_EXTS.some(ext => filePath.endsWith(ext))) {
64	        const basename = path.basename(filePath, path.extname(filePath));
