67	        let memory = { version: '1.0', lastUpdated: '', entries: [] };
68	        try { memory = JSON.parse(fs.readFileSync(MEMORY_FILE, 'utf-8')); } catch (_) {}
69	
70	        const entry = {
71	            date: new Date().toISOString().slice(0, 10),
72	            component: basename,
73	            file: filePath.replace('/Users/marcelspatz/NUDIMMUD/', ''),
74	            action: isNew ? 'create' : 'edit',
75	            decision: isNew ? `New component created: ${basename}` : `Updated: ${basename}`
76	        };
77	
78	        const alreadyLogged = memory.entries.some((e) =>
79	            e.file === entry.file && e.date === entry.date && e.action === entry.action
80	        );
81	
82	        if (!alreadyLogged) {
83	            memory.entries = [entry, ...memory.entries].slice(0, 100);
84	            memory.lastUpdated = new Date().toISOString();
85	            fs.writeFileSync(MEMORY_FILE, JSON.stringify(memory, null, 2));
86	        }
